const filas = $input.all().map(item => item.json);

// Filtramos filas que tengan al menos fecha y producto
const validas = filas.filter(f => f.fecha && f.producto);

// Ordenamos por fecha descendente (más reciente arriba)
validas.sort((a, b) => new Date(b.fecha) - new Date(a.fecha));

// Nos quedamos solo con las 10 primeras
const ultimas10 = validas.slice(0, 10);

// Devolvemos un único objeto con la lista dentro
return [
  {
    json: {
      items: ultimas10
    }
  }
];

// Combina info_util (clave-valor) con próximos cortes activos
// Nota: este Code se ejecuta una vez ('Run Once for All Items')
const infoUtil = {};
for (const item of $('Get info_util').all()) {
  const c = item.json.clave;
  if (c) infoUtil[String(c).trim()] = item.json.valor || '';
}

const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

// Dedup por (genetica + fecha) — Get eventos_corte puede ejecutarse N veces
const visto = new Set();
const cortes = [];
for (const it of $('Get eventos_corte').all()) {
  const r = it.json || {};
  if (String(r.estado || '').toLowerCase() !== 'activo') continue;
  if (!r.fecha_proximo_corte_estimada) continue;
  const key = (r.genetica || '') + '|' + r.fecha_proximo_corte_estimada;
  if (visto.has(key)) continue;
  visto.add(key);
  const f = new Date(r.fecha_proximo_corte_estimada);
  f.setHours(0, 0, 0, 0);
  const diasRestantes = Math.round((f - hoy) / 86400000);
  cortes.push({
    genetica: r.genetica || '',
    fecha: r.fecha_proximo_corte_estimada,
    dias_restantes: diasRestantes
  });
}
cortes.sort((a, b) => a.dias_restantes - b.dias_restantes);

return [{
  json: {
    fase_actual: infoUtil.fase_actual || 'floracion',
    inicio_floracion: infoUtil.inicio_floracion || '',
    inicio_crecimiento: infoUtil.inicio_crecimiento || '',
    proximos_cortes: cortes.slice(0, 5)
  }
}];

const filas = $input.all().map(item => item.json);

const productos = filas
  .map(f => ({
    producto: (f.producto || '').trim()
  }))
  .filter(f => f.producto !== '');

return [
  {
    json: {
      items: productos
    }
  }
];

const filas = $input.all().map(item => item.json);

const zonas_validas = ['madres', 'esquejes', 'floracion', 'limpieza', 'mantenimiento'];
const orden_prioridad = { alta: 1, media: 2, baja: 3 };

const tareas_agrupadas = {
  madres: [],
  esquejes: [],
  floracion: [],
  limpieza: [],
  mantenimiento: []
};

for (const fila of filas) {
  const id = String(fila.id || '').trim();
  const zona = String(fila.zona || '').trim().toLowerCase();
  const tarea = String(fila.tarea || '').trim();
  const prioridad = String(fila.prioridad || 'media').trim().toLowerCase();
  const estado = String(fila.estado || '').trim().toLowerCase();
  const fecha = String(fila.fecha || '').trim();
  const recurrente = String(fila.recurrente || '').trim().toLowerCase();
  const dia_recurrencia = String(fila.dia_recurrencia || '').trim().toLowerCase();
  const observaciones = String(fila.observaciones || '').trim();

  if (!id || !zona || !tarea) {
    continue;
  }

  if (!zonas_validas.includes(zona)) {
    continue;
  }

  if (estado === 'hecha') {
    continue;
  }

  tareas_agrupadas[zona].push({
    id,
    zona,
    tarea,
    prioridad: orden_prioridad[prioridad] ? prioridad : 'media',
    estado,
    fecha,
    recurrente,
    dia_recurrencia,
    observaciones
  });
}

for (const zona of zonas_validas) {
  tareas_agrupadas[zona].sort((a, b) => {
    const prioridad_a = orden_prioridad[a.prioridad] || 99;
    const prioridad_b = orden_prioridad[b.prioridad] || 99;

    if (prioridad_a !== prioridad_b) {
      return prioridad_a - prioridad_b;
    }

    return a.tarea.localeCompare(b.tarea, 'es');
  });
}

return [
  {
    json: {
      items_por_zona: tareas_agrupadas
    }
  }
];

const idBuscado = String($('webhook tareas eliminar').first().json.body.id || '').trim();

if (!idBuscado) {
  throw new Error('falta_id');
}

const filas = $input.all().map(item => item.json);
const coincidencias = filas.filter(f => String(f.id || '').trim() === idBuscado);

if (coincidencias.length === 0) {
  throw new Error(`tarea_no_encontrada: ${idBuscado}`);
}

if (coincidencias.length > 1) {
  throw new Error(`id_duplicado: ${idBuscado} aparece ${coincidencias.length} veces en el Sheet`);
}

const tareaEncontrada = coincidencias[0];

return [{
  json: {
    row_number: tareaEncontrada.row_number,
    id: tareaEncontrada.id,
    tarea: tareaEncontrada.tarea,
    estado: 'hecha'
  }
}];

// Usar DateTime (Luxon) para timezone correcto (Europa/Madrid)
const ahora = DateTime.now().setZone('Europe/Madrid');
const diasSemana = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
const diaHoy = diasSemana[ahora.weekday % 7]; // Luxon: 1=lunes...7=domingo
const fechaHoy = ahora.toFormat('yyyy-MM-dd');

// Luxon weekday: 1=lunes, 2=martes, ..., 7=domingo
// Nuestro array: 0=domingo, 1=lunes, ..., 6=sabado
const diaLuxon = ahora.weekday === 7 ? 'domingo' : diasSemana[ahora.weekday];

const plantillas = $('Leer Plantillas1').all().map(item => item.json);
const tareasExistentes = $('Leer Tareas Existentes1').all().map(item => item.json);

// Filtrar plantillas activas que aplican hoy
// Soporta dias multiples: "lunes,miercoles,viernes"
const plantillasHoy = plantillas.filter(p => {
  const activa = String(p.activa || '').trim().toLowerCase();
  if (activa !== 'si') return false;

  const diasConfig = String(p.dia_recurrencia || '').trim().toLowerCase();
  // Soportar multiples dias separados por coma
  const diasArray = diasConfig.split(',').map(d => d.trim());
  return diasArray.includes(diaLuxon);
});

if (plantillasHoy.length === 0) {
  // Retornar item informativo para logging en n8n
  return [{ json: { _skip: true, mensaje: `Sin plantillas para ${diaLuxon} (${fechaHoy})` } }];
}

// Verificar duplicados: misma tarea + zona + fecha de hoy
const nuevas = plantillasHoy.filter(p => {
  const yaExiste = tareasExistentes.some(t => {
    return String(t.tarea || '').trim().toLowerCase() === String(p.tarea || '').trim().toLowerCase()
      && String(t.zona || '').trim().toLowerCase() === String(p.zona || '').trim().toLowerCase()
      && String(t.fecha || '').trim() === fechaHoy
      && String(t.estado || '').trim().toLowerCase() !== 'hecha';
  });
  return !yaExiste;
});

if (nuevas.length === 0) {
  return [{ json: { _skip: true, mensaje: `Todas las tareas de ${diaLuxon} ya existen para ${fechaHoy}` } }];
}

// Generar IDs incrementales
let maxId = 0;
for (const t of tareasExistentes) {
  const id = parseInt(t.id);
  if (!isNaN(id) && id > maxId) maxId = id;
}

return nuevas.map((p, i) => ({
  json: {
    id: String(maxId + 1 + i),
    zona: p.zona || '',
    tarea: p.tarea || '',
    prioridad: p.prioridad || 'media',
    estado: 'pendiente',
    fecha: fechaHoy,
    recurrente: 'si',
    dia_recurrencia: p.dia_recurrencia || '',
    observaciones: p.observaciones || ''
  }
}));

const body = $('Webhook Crear').first().json.body;

const tarea = String(body.tarea || '').trim();
const zona = String(body.zona || '').trim().toLowerCase();
const prioridad = String(body.prioridad || 'media').trim().toLowerCase();
const fecha = String(body.fecha || '').trim();
const observaciones = String(body.observaciones || '').trim();

// Sufijo random de 3 digitos para evitar colisiones cuando varias ejecuciones caen en el mismo milisegundo
const id = 'T' + Date.now() + String(Math.floor(Math.random() * 900 + 100));

return [{
  json: {
    id,
    zona,
    tarea,
    prioridad,
    estado: 'pendiente',
    fecha,
    recurrente: '',
    dia_recurrencia: '',
    observaciones
  }
}];

const idBuscado = $('Webhook Posponer').first().json.body.id;
const nuevaFecha = $('Webhook Posponer').first().json.body.nueva_fecha;
const filas = $input.all().map(item => item.json);
const tarea = filas.find(f => String(f.id || '').trim() === String(idBuscado || '').trim());

if (!tarea) {
  return [{ json: { encontrada: false, error: 'tarea_no_encontrada' } }];
}

return [{ json: { encontrada: true, id: tarea.id, nueva_fecha: nuevaFecha } }];

const idBuscado = $('Webhook Eliminar').first().json.body.id;
const filas = $input.all().map(i => i.json);
const item = filas.find(f => String(f.id || '').trim() === String(idBuscado || '').trim());
if (!item) return [{ json: { encontrado: false } }];
return [{ json: { encontrado: true, id: item.id, estado: 'comprado' } }];

const body = $('Webhook Agregar').first().json.body;
const item = String(body.item || '').trim();
const id = 'C' + Date.now();
return [{ json: { id, item, estado: 'pendiente' } }];

const filas = $input.all().map(i => i.json);
const pendientes = filas.filter(f => String(f.estado || '').trim().toLowerCase() === 'pendiente');
return [{ json: { items: pendientes } }];

// Recibe { fase: "floracion"|"crecimiento", fecha: "YYYY-MM-DD" }
const body = $input.first().json.body || $input.first().json || {};
const faseRaw = String(body.fase || 'floracion').toLowerCase();
const fase = (faseRaw === 'crecimiento') ? 'crecimiento' : 'floracion';
const fecha = String(body.fecha || '').slice(0, 10);

if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) {
  throw new Error('Fecha inválida (YYYY-MM-DD requerido)');
}

const ahora = new Date();
const ts = ahora.getFullYear() + '-' +
  String(ahora.getMonth() + 1).padStart(2, '0') + '-' +
  String(ahora.getDate()).padStart(2, '0') + ' ' +
  String(ahora.getHours()).padStart(2, '0') + ':' +
  String(ahora.getMinutes()).padStart(2, '0');

const claveFecha = (fase === 'crecimiento') ? 'inicio_crecimiento' : 'inicio_floracion';

return [
  { json: { clave: 'fase_actual', valor: fase, actualizado_en: ts } },
  { json: { clave: claveFecha, valor: fecha, actualizado_en: ts } }
];

const productos = $('Read productos_ipm Sugerir').all().map(i => i.json);
const aplicaciones = $('Read Control_IPM Sugerir').all().map(i => i.json);

const trigger = $('Webhook IPM Sugerir').first().json;
const pool = String((trigger.query && trigger.query.pool) || '').trim();
const aptoCosechaParam = String((trigger.query && trigger.query.apto_cosecha) || '').trim().toLowerCase();
const filtraAptoCosecha = aptoCosechaParam === 'si' || aptoCosechaParam === 'true';
const dosisModo = String((trigger.query && trigger.query.dosis_modo) || 'preventiva').trim().toLowerCase();
const zona = String((trigger.query && trigger.query.zona) || '').trim();

if (!pool) {
  return [{ json: {
    success: false,
    error: "query param 'pool' requerido (regular_madres / mensual_acaros / foliar_nutricional)"
  } }];
}

// Parsear fecha tolerando 'DD/MM/YYYY' y 'YYYY-MM-DD'
function parseFecha(s) {
  if (!s) return null;
  s = String(s).trim();
  const m1 = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m1) {
    const dt = new Date(Number(m1[3]), Number(m1[2]) - 1, Number(m1[1]));
    return isNaN(dt.getTime()) ? null : dt;
  }
  const m2 = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m2) {
    const dt = new Date(Number(m2[1]), Number(m2[2]) - 1, Number(m2[3]));
    return isNaN(dt.getTime()) ? null : dt;
  }
  const fallback = new Date(s);
  return isNaN(fallback.getTime()) ? null : fallback;
}

// Última aplicación por producto (matching exacto sobre Control_IPM.producto)
const ultimaPorProducto = {};
for (const a of aplicaciones) {
  const prod = String(a.producto || '').trim();
  if (!prod) continue;
  const fecha = parseFecha(a.fecha);
  if (!fecha) continue;
  if (!ultimaPorProducto[prod] || fecha > ultimaPorProducto[prod]) {
    ultimaPorProducto[prod] = fecha;
  }
}

const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

const candidatos = productos
  .filter(p => String(p.activo || '').trim().toLowerCase() === 'si')
  .filter(p => String(p.pool || '').trim() === pool)
  .filter(p => !filtraAptoCosecha || String(p.apto_cosecha || '').trim().toLowerCase() === 'si')
  .map(p => {
    const ult = ultimaPorProducto[p.producto];
    const dias = ult ? Math.floor((hoy - ult) / (1000 * 60 * 60 * 24)) : 9999;
    const carencia = Number(p.intervalo_carencia_dias) || 0;
    const cumple = dias >= carencia;
    let dosis = '';
    if (dosisModo === 'curativa' && p.dosis_curativa) dosis = p.dosis_curativa;
    else dosis = p.dosis_preventiva || p.dosis_curativa || '';
    return {
      producto: p.producto,
      principio_activo: p.principio_activo,
      familia_irac: p.familia_irac,
      target_principal: p.target_principal,
      agresividad: p.agresividad,
      dosis_sugerida: dosis,
      apto_cosecha: p.apto_cosecha,
      pool: p.pool,
      dias_desde_ultima: dias,
      carencia_minima: carencia,
      cumple_carencia: cumple,
    };
  });

if (candidatos.length === 0) {
  return [{ json: {
    success: true, pool, zona, apto_cosecha: filtraAptoCosecha,
    sugerido: null, alternativas: [], bloqueados_por_carencia: [],
    motivo: "No hay productos catalogados en este pool con los filtros aplicados."
  } }];
}

const elegibles = candidatos.filter(c => c.cumple_carencia);
elegibles.sort((a, b) => b.dias_desde_ultima - a.dias_desde_ultima);

const sugerido = elegibles[0] || null;

let motivoSugerencia = '';
if (sugerido) {
  if (sugerido.dias_desde_ultima === 9999) {
    motivoSugerencia = `Producto sin aplicaciones registradas — primer uso recomendado.`;
  } else {
    motivoSugerencia = `${sugerido.dias_desde_ultima}d desde la ultima aplicacion (carencia minima ${sugerido.carencia_minima}d).`;
  }
}

return [{ json: {
  success: true,
  pool,
  zona,
  apto_cosecha: filtraAptoCosecha,
  dosis_modo: dosisModo,
  sugerido: sugerido ? { ...sugerido, motivo: motivoSugerencia } : null,
  alternativas: elegibles.slice(1, 4),
  bloqueados_por_carencia: candidatos.filter(c => !c.cumple_carencia).map(c => ({
    producto: c.producto,
    dias_desde_ultima: c.dias_desde_ultima,
    carencia_minima: c.carencia_minima,
    le_falta_dias: Math.max(0, c.carencia_minima - c.dias_desde_ultima),
  })),
} }];
